const express = require('express');
const { StorageRpcClient } = require('@workspace/storage-client');
const { verifySession } = require('./auth');
const { db } = require('./database');

const app = express();

const storageClient = new StorageRpcClient({
  endpoint: 'http://storage-daemon.internal.mesh:9090',
  serviceKey: process.env.INTERNAL_STORAGE_M2M_KEY
});

app.get('/api/documents/download-link', verifySession, async (req, res) => {
  const { fileKey, exportFormat } = req.query;

  if (!fileKey || typeof fileKey !== 'string') {
    return res.status(400).json({ error: 'fileKey is required' });
  }

  // Check database ownership against the authenticated user's organization
  const document = await db.query(
    'SELECT id, tenant_id FROM documents WHERE file_key = $1 AND tenant_id = $2',
    [fileKey, req.user.tenantId]
  );

  if (document.rows.length === 0) {
    return res.status(404).json({ error: 'Document not found or access denied' });
  }

  try {
    const signedUrlData = await storageClient.generateInternalSignedDownloadUrl({
      fileKey,
      format: exportFormat || 'raw',
      callingService: 'api-gateway',
      tenantId: req.user.tenantId
    });

    res.json({ downloadUrl: signedUrlData.url, expiresAt: signedUrlData.expiresAt });
  } catch (error) {
    res.status(502).json({ error: 'Storage cluster unreachable' });
  }
});

app.listen(8082);
